_spawn.source:
def _spawn(self, name, fn):
        def target():
            try:
                fn()
            except BaseException as exc:
                self._errors.append((name, repr(exc)))
            finally:
                connections.close_all()

        thread = threading.Thread(target=target, name=name, daemon=True)
        thread.start()
        return thread

